xml.Script:
        BumpColor := 'FF0000'; // Red

        R := 0.6;
        H := R * 1.0;

        D := R * 0.3;

        DX := -0.03;
        DY := -0.06;
        DZ :=  0.20;

        N := 6;
        A := 2*Pi / N;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(A * i);
            y[i] := R * sin(A * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
